+                    clusterService.removeListener(listener);
+                }
+
+                @Override
+                public void onFailure(String source, Exception e) {
+                    logger.warn(
+                        "upgrading frozen indices to have frozen shard limit group failed, will retry on the next cluster state update",
+                        e
+                    );
